package lombok.bytecode;

import java.io.PrintWriter;
import java.io.StringWriter;
import java.util.concurrent.atomic.AtomicBoolean;

import lombok.core.DiagnosticsReceiver;
import lombok.core.PostCompilerTransformation;
import lombok.spi.Provides;

import org.objectweb.asm.ClassReader;
import org.objectweb.asm.ClassVisitor;
import org.objectweb.asm.ClassWriter;
import org.objectweb.asm.MethodVisitor;
import org.objectweb.asm.Opcodes;
import org.objectweb.asm.commons.JSRInlinerAdapter;

@Provides
public class PreventNullAnalysisRemover implements PostCompilerTransformation {

	@Override public byte[] applyTransformations(byte[] original, String fileName, DiagnosticsReceiver diagnostics) {
		try {
			ClassFileMetaData classFileMetaData = new ClassFileMetaData(original);
			if (!classFileMetaData.usesMethod("lombok/Lombok", "preventNullAnalysis")) {
				return null;
			}
			boolean exactPreventNullAnalysis = classFileMetaData.usesMethod("lombok/Lombok", "preventNullAnalysis", "(Ljava/lang/Object;)Ljava/lang/Object;");

			final byte utf8Tag = 1;
			final byte integerTag = 3;
			final byte floatTag = 4;
			final byte longTag = 5;
			final byte doubleTag = 6;
			final byte classTag = 7;
			final byte stringTag = 8;
			final byte fieldTag = 9;
			final byte methodTag = 10;
			final byte interfaceMethodTag = 11;
			final byte nameTypeTag = 12;
			final byte methodHandleTag = 15;
			final byte methodTypeTag = 16;
			final byte dynamicTag = 17;
			final byte invokeDynamicTag = 18;
			final byte moduleTag = 19;
			final byte packageTag = 20;
			int[] poolEntryExtraBytes = new int[21];
			poolEntryExtraBytes[classTag] = 2;
			poolEntryExtraBytes[stringTag] = 2;
			poolEntryExtraBytes[methodTypeTag] = 2;
			poolEntryExtraBytes[moduleTag] = 2;
			poolEntryExtraBytes[packageTag] = 2;
			poolEntryExtraBytes[methodHandleTag] = 3;
			poolEntryExtraBytes[integerTag] = 4;
			poolEntryExtraBytes[floatTag] = 4;
			poolEntryExtraBytes[fieldTag] = 4;
			poolEntryExtraBytes[methodTag] = 4;
			poolEntryExtraBytes[interfaceMethodTag] = 4;
			poolEntryExtraBytes[nameTypeTag] = 4;
			poolEntryExtraBytes[invokeDynamicTag] = 4;
			poolEntryExtraBytes[dynamicTag] = 4;
			poolEntryExtraBytes[longTag] = 8;
			poolEntryExtraBytes[doubleTag] = 8;

			int constantPoolCount = ((original[8] & 0xFF) << 8) | (original[9] & 0xFF);
			int[] poolOffsets = new int[constantPoolCount];
			byte[] poolTypes = new byte[constantPoolCount];
			String[] poolUtf8s = new String[constantPoolCount];
			int cursor = 10;
			for (int poolIndex = 1; poolIndex < constantPoolCount; poolIndex++) {
				byte poolType = original[cursor];
				poolTypes[poolIndex] = poolType;
				cursor++;
				poolOffsets[poolIndex] = cursor;
				if (poolType == utf8Tag) {
					int utf8ByteLength = ((original[cursor] & 0xFF) << 8) | (original[cursor + 1] & 0xFF);
					cursor += 2;
					int utf8End = cursor + utf8ByteLength;
					char[] utf8Chars = new char[utf8ByteLength];
					int utf8CharCount = 0;
					int utf8Pos = cursor;
					while (utf8Pos < utf8End) {
						int lead = original[utf8Pos++] & 0xFF;
						if (lead < 0x80) {
							utf8Chars[utf8CharCount++] = (char) lead;
						} else if ((lead & 0xE0) == 0xC0) {
							if (utf8Pos >= utf8End) {
								break;
							}
							int sixBits = original[utf8Pos++] & 0x3F;
							utf8Chars[utf8CharCount++] = (char) (((lead & 0x1F) << 6) | sixBits);
						} else {
							if (utf8Pos + 1 >= utf8End) {
								break;
							}
							int middleBits = original[utf8Pos++] & 0x3F;
							int lowBits = original[utf8Pos++] & 0x3F;
							utf8Chars[utf8CharCount++] = (char) (((lead & 0x0F) << 12) | (middleBits << 6) | lowBits);
						}
					}
					poolUtf8s[poolIndex] = new String(utf8Chars, 0, utf8CharCount);
					cursor = utf8End;
				} else if (poolType == longTag || poolType == doubleTag) {
					cursor += 8;
					poolIndex++;
				} else {
					if (poolType < 0 || poolType >= poolEntryExtraBytes.length || poolEntryExtraBytes[poolType] <= 0) {
						throw new AssertionError("Unknown constant pool type " + poolType);
					}
					cursor += poolEntryExtraBytes[poolType];
				}
			}

			int lombokClassUtf8Index = -1;
			int preventNullAnalysisUtf8Index = -1;
			int preventNullAnalysisDescriptorUtf8Index = -1;
			for (int poolIndex = 1; poolIndex < constantPoolCount; poolIndex++) {
				if (poolTypes[poolIndex] != utf8Tag) {
					continue;
				}
				String utf8Value = poolUtf8s[poolIndex];
				if ("lombok/Lombok".equals(utf8Value)) {
					lombokClassUtf8Index = poolIndex;
				}
				if ("preventNullAnalysis".equals(utf8Value)) {
					preventNullAnalysisUtf8Index = poolIndex;
				}
				if ("(Ljava/lang/Object;)Ljava/lang/Object;".equals(utf8Value)) {
					preventNullAnalysisDescriptorUtf8Index = poolIndex;
				}
			}

			int lombokClassIndex = -1;
			for (int poolIndex = 1; poolIndex < constantPoolCount; poolIndex++) {
				if (poolTypes[poolIndex] != classTag) {
					continue;
				}
				int nameIndex = ((original[poolOffsets[poolIndex]] & 0xFF) << 8) | (original[poolOffsets[poolIndex] + 1] & 0xFF);
				if (nameIndex == lombokClassUtf8Index) {
					lombokClassIndex = poolIndex;
					break;
				}
			}

			boolean methodReferenceFound = false;
			boolean exactMethodReferenceFound = false;
			for (int poolIndex = 1; poolIndex < constantPoolCount; poolIndex++) {
				byte poolType = poolTypes[poolIndex];
				if (poolType != methodTag) {
					if (poolType != interfaceMethodTag) {
						continue;
					}
				}
				int classIndex = ((original[poolOffsets[poolIndex]] & 0xFF) << 8) | (original[poolOffsets[poolIndex] + 1] & 0xFF);
				if (classIndex != lombokClassIndex) {
					continue;
				}
				int nameAndTypeIndex = ((original[poolOffsets[poolIndex] + 2] & 0xFF) << 8) | (original[poolOffsets[poolIndex] + 3] & 0xFF);
				int nameIndex = ((original[poolOffsets[nameAndTypeIndex]] & 0xFF) << 8) | (original[poolOffsets[nameAndTypeIndex] + 1] & 0xFF);
				if (nameIndex != preventNullAnalysisUtf8Index) {
					continue;
				}
				methodReferenceFound = true;
				int descriptorIndex = ((original[poolOffsets[nameAndTypeIndex] + 2] & 0xFF) << 8) | (original[poolOffsets[nameAndTypeIndex] + 3] & 0xFF);
				exactMethodReferenceFound = descriptorIndex == preventNullAnalysisDescriptorUtf8Index;
			}

			String ownerToRemove = "lombok/Lombok";
			String nameToRemove = "preventNullAnalysis";
			String descriptorToRemove = "(Ljava/lang/Object;)Ljava/lang/Object;";
			if (methodReferenceFound) {
				if (lombokClassUtf8Index != -1) {
					ownerToRemove = poolUtf8s[lombokClassUtf8Index];
				}
				if (preventNullAnalysisUtf8Index != -1) {
					nameToRemove = poolUtf8s[preventNullAnalysisUtf8Index];
				}
				if (preventNullAnalysisDescriptorUtf8Index != -1) {
					descriptorToRemove = poolUtf8s[preventNullAnalysisDescriptorUtf8Index];
				}
			}

			final boolean removeExactCall = exactPreventNullAnalysis || exactMethodReferenceFound;

			ClassReader jsrReader = new ClassReader(original);
			ClassWriter jsrWriter = new FixedClassWriter(jsrReader, 0);
			ClassVisitor jsrVisitor = new ClassVisitor(Opcodes.ASM9, jsrWriter) {
				@Override public MethodVisitor visitMethod(int access, String name, String desc, String signature, String[] exceptions) {
					return new JSRInlinerAdapter(super.visitMethod(access, name, desc, signature, exceptions), access, name, desc, signature, exceptions);
				}
			};
			jsrReader.accept(jsrVisitor, 0);
			byte[] fixedByteCode = jsrWriter.toByteArray();

			ClassReader reader = new ClassReader(fixedByteCode);
			ClassWriter writer = new FixedClassWriter(reader, 0);

			final AtomicBoolean changesMade = new AtomicBoolean();
			final String ownerName = ownerToRemove;
			final String methodName = nameToRemove;
			final String methodDescriptor = descriptorToRemove;

			class PreventNullAnalysisVisitor extends MethodVisitor {
				PreventNullAnalysisVisitor(MethodVisitor mv) {
					super(Opcodes.ASM9, mv);
				}

				@Override public void visitMethodInsn(int opcode, String owner, String name, String desc, boolean itf) {
					boolean hit = removeExactCall;
					if (hit && opcode != Opcodes.INVOKESTATIC) hit = false;
					if (hit && !methodName.equals(name)) hit = false;
					if (hit && !ownerName.equals(owner)) hit = false;
					if (hit && !methodDescriptor.equals(desc)) hit = false;
					if (hit) {
						changesMade.set(true);
						if (System.getProperty("lombok.debugAsmOnly", null) != null) super.visitMethodInsn(opcode, owner, name, desc, itf); // DEBUG for issue 470!
					} else {
						super.visitMethodInsn(opcode, owner, name, desc, itf);
					}
				}
			}

			reader.accept(new ClassVisitor(Opcodes.ASM9, writer) {
				@Override public MethodVisitor visitMethod(int access, String name, String desc, String signature, String[] exceptions) {
					return new PreventNullAnalysisVisitor(super.visitMethod(access, name, desc, signature, exceptions));
				}
			}, 0);
			if (changesMade.get()) {
				return writer.toByteArray();
			}
			return null;
		} catch (Exception e) {
			StringWriter stackTrace = new StringWriter();
			e.printStackTrace(new PrintWriter(stackTrace, true));
			diagnostics.addError(String.format("Error during the transformation of '%s'; post-compiler '%s' caused an exception: %s", fileName, PreventNullAnalysisRemover.class.getName(), stackTrace));
			return null;
		}
	}
}

